ALTER CATALOG prod ENABLE PREDICTIVE OPTIMIZATION;
ALTER SCHEMA prod.staging DISABLE PREDICTIVE OPTIMIZATION;
ALTER TABLE prod.sales.orders INHERIT PREDICTIVE OPTIMIZATION;

DESCRIBE CATALOG EXTENDED prod;

CREATE TABLE sales.orders (order_id BIGINT, customer_id BIGINT, order_date DATE)
CLUSTER BY (order_date, customer_id);

ALTER TABLE sales.orders CLUSTER BY (customer_id);
OPTIMIZE sales.orders FULL;
OPTIMIZE sales.orders FULL WHERE order_date >= '2026-10-01';

ALTER TABLE sales.events CLUSTER BY AUTO;
ALTER TABLE sales.legacy REPLACE PARTITIONED BY WITH CLUSTER BY (event_date, id);
OPTIMIZE sales.legacy;

ALTER TABLE sales.orders CLUSTER BY NONE;
